  0 <= nf -> 4 * nf <= mfa -> mfa <= mfa' <= K_FREEARR_MAX ->
  In iv (rec_W L sp c kk n nf mfa mfa') ->
  let AB := aslot_addr L c kk in let S := size_of_class c in
  iv = (sp - 688, sp) \/ (AB <= fst iv /\ snd iv <= AB + S) \/ lowpiece L c iv.
Proof.
