(* [comment removed for export] *)
Definition np_fp (L : alayout) (HI : Z) (LB : list ablock) (W : list (Z * Z)) : Prop :=
  forall iv, In iv W -> forall a, fst iv <= a < snd iv -> ~ cprot L HI LB a.

